{
  "findings": [
    {
      "check_id": "CKV2_AWS_40",
      "title": "Ensure AWS IAM policy does not allow full IAM privileges",
      "resource": "aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint",
      "severity": "MEDIUM",
      "explanation": "The attached IAM policy may allow full IAM privileges, which can lead to privilege escalation or unauthorized access. This should be reviewed and restricted to the minimum necessary permissions."
    }
  ],
  "patched_code": "resource "aws_iam_user_policy_attachment" "privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy" {
  user       = aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name
  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn
}

resource "aws_iam_policy" "privesc19-UpdateExistingGlueDevEndpoint" {
  name        = "privesc19-UpdateExistingGlueDevEndpoint-policy"
  description = "Policy with restricted permissions for Glue Dev Endpoint"

  policy = <<EOF
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": [
        "glue:UpdateDevEndpoint"
      ],
      "Resource": "arn:aws:glue:*:*:devEndpoint/*"
    }
  ]
}
EOF
}
",
  "fix_summary": "Restricted the IAM policy to only allow the 'glue:UpdateDevEndpoint' action on Glue Dev Endpoints, reducing the risk of privilege escalation."
}
